-- ---------------------------------------------------------------- housekeeping
-- Room numbering continues after the highest room of each major.
UPDATE formation_scopes f SET room_seq = GREATEST(f.room_seq,
    COALESCE((SELECT max(g.room_no) FROM student_groups g WHERE g.scope_id = f.id), 0));
-- Students sign in with Google only; fixture lecturers count as imported Moderator accounts.
UPDATE users SET password_hash = NULL WHERE role = 'STUDENT';
UPDATE users SET lecturer_imported = TRUE
WHERE role = 'LECTURER' AND id IN ('71000000-0000-0000-0000-000000000001',
    '71000000-0000-0000-0000-000000000002', '71000000-0000-0000-0000-000000000003');
